INSERT INTO LocalizedText (Language, Tag, Text) VALUES
('ko_KR', 'TXT_KEY_BUILDING_NATIVEMOUND', '플랫폼 마운드'),
('ko_KR', 'TXT_KEY_BUILDING_AUL', '아울'),
('ko_KR', 'TXT_KEY_BUILDING_SACREDCAVE', '신성한 동굴'),
('ko_KR', 'TXT_KEY_BUILDING_XUEMIAO', '공묘'),
('ko_KR', 'TXT_KEY_BUILDING_JINJA', '신사'),
('ko_KR', 'TXT_KEY_BUILDING_GOMPA', '곰파'),
('ko_KR', 'TXT_KEY_BUILDING_NATIVEMOUND_STRATEGY', '플랫폼 마운드 신앙을 따르는 종교의 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 플랫폼 마운드를 건설하면 식량과 골드를 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_AUL_STRATEGY', '아울 신앙을 따르는 종교 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 아울을 건설하면 도시에서 신앙, 위대한 장군 점수를 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_SACREDCAVE_STRATEGY', '신성한 동굴 신앙을 따르는 종교 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 신성한 동굴을 건설하면 신앙과 관광을 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_XUEMIAO_STRATEGY', '공묘 신앙을 따르는 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 공자묘를 건설하면 신앙, 과학, 골드를 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_JINJA_STRATEGY', '신사 신앙을 따르는 종교 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 신사를 건설하면 신앙, 문화, 위대한 제독 점수를 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_GOMPA_STRATEGY', '곰파 신앙을 따르는 종교 도시에서만 건설할 수 있습니다. [ICON_PEACE] 신앙으로 구매하여 이 건물을 건설하세요. 곰파를 건설하면 신앙, 과학, 식량을 얻을 수 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_NATIVEMOUND_TEXT', '북미 동부 산림지대에서 원주민 문화는 마운드라는 기념비적인 토루를 건설했는데, 이는 사회, 종교, 정치 생활의 중요한 중심지 역할을 했습니다. 이러한 마운드는 크기와 모양이 다양하며, 종종 흙과 점토 층으로 만들어졌으며, 때로는 높이가 수십 피트에 달하기도 했습니다. 그들은 원뿔형 무덤, 의식용 구조물을 위한 플랫폼형 무덤, 동물 모양의 인형 무덤 등의 형태를 취할 수 있었습니다. 일리노이주에 있는 카호키아, 앨라배마주에 있는 마운드빌, 루이지애나주에 있는 포버티 포인트와 같은 유적지는 수천 년에 걸친 마운드 건축 전통의 규모와 정교함을 보여줍니다. 이러한 마운드를 건설하는 데는 조직적인 노동과 계획이 필요했는데, 이는 마운드를 건설한 사회의 복잡성과 응집력을 반영합니다.[NEWLINE][NEWLINE]미국 동부에서 마운드 건축의 역사는 원시 시대(포버티 포인트에서 기원전 3500년경)부터 우들랜드와 미시시피 시대를 거쳐 서기 800년에서 1600년 사이에 정점을 이루었습니다. 가장 초기의 마운드는 주로 매장지였지만, 이후 문화에서는 플랫폼 마운드를 사원, 공공주택, 엘리트 거주지의 기초로 사용하여 종교적 권위와 정치적 권력을 모두 상징했습니다. 이러한 구조물의 목적은 다면적이었습니다. 죽은 자를 기리고, 의례와 제의 공간으로 사용되었으며, 사회적 위계를 강화하고, 우주론과 지역 정체성을 구체적으로 표현했습니다. 유럽의 식민지화로 인해 이러한 전통이 붕괴된 후에도, 이 마운드의 유산은 북미 동부 지역 원주민의 독창성, 영성, 조직력에 대한 증거로 남아 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_AUL_TEXT', '아시아 문화권, 특히 중앙아시아에서 아울은 오랫동안 유목민과 반유목민의 생활 방식과 연관되어 온 전통적인 농촌 거주지 또는 야영지를 의미합니다. 일반적으로 유르트나 이후의 영구 주택이 모여 이루어진 아울은 튀르크족, 몽골족, 카자흐족 등의 거주 및 사회적 단위로 사용되었습니다. 그 배치는 가족과 일족이 가까이 모여 자원을 공유하고, 가축을 키우고, 문화적 또는 종교적 의식을 거행하는 공동생활을 반영했습니다. 거주 공간이라는 실질적인 역할 외에도 아울은 대초원 환경과의 조화와 친족 관계, 환대, 집단 정체성의 가치를 구현하는 상징적 의미도 지니고 있었습니다.[NEWLINE][NEWLINE]역사적으로 아울은 아시아의 광활한 초원을 계절에 따라 이동하며 살았던 유목민 문화권의 주요 정착 형태로 발전했습니다. 수세기 동안 그들은 말, 양, 소를 중심으로 한 목축 경제를 뒷받침하여 생태계 순환에 따른 이동성과 적응을 촉진했습니다. 몽골 제국과 같은 제국의 부상과 함께 아울은 중요한 조직 단위로 자리 잡았고, 대규모 이주와 조정을 가능하게 했습니다. 시간이 흐르면서, 특히 18~19세기에 러시아 제국이 확장되고 이후 소련이 통치하는 동안 많은 마을이 더욱 영구적인 마을로 전환되었으며, 종종 이름은 그대로 유지했지만 고정된 주거지를 채택했습니다. 오늘날 카자흐스탄, 키르기스스탄, 몽골 등의 나라에서는 "아울"이라는 용어가 여전히 작은 농촌 지역 사회를 묘사하는 데 사용되고 있으며, 이는 살아있는 전통과 대초원 문화의 역사적 회복력을 상징합니다.'),
('ko_KR', 'TXT_KEY_BUILDING_SACREDCAVE_TEXT', '신성한 동굴은 전 세계 많은 문화권에서 중요한 역할을 해왔으며, 의식, 영적, 종교적 목적을 위한 자연 성소 역할을 해왔습니다. 동굴은 일상 생활과 분리되어 있어 숨겨져 있고 경계적인 성격을 띠고 있어 다산, 지하 세계, 신의 존재와 관련된 의식을 치르기에 이상적인 장소였습니다. 일부 전통에서는 동굴을 창조나 재생을 상징하는 자궁과 같은 공간으로 여겼고, 다른 전통에서는 동굴을 영혼의 세계로 통하는 문으로 여겼습니다. 고고학적 증거에 따르면 동굴은 제물, 매장, 환상 탐색에 사용되었으며, 종종 신성한 의미를 나타내는 암각화, 조각품, 제단이 발견되었습니다.[NEWLINE][NEWLINE]신성한 동굴의 역사는 수만 년 전으로 거슬러 올라갑니다. 초기 인류가 라스코 동굴과 같은 동굴 깊숙한 곳에 동물을 그린 구석기 시대 유럽부터, 마야와 아즈텍이 동굴을 지하 세계로 가는 입구로 여겼던 중미의 의식 동굴(시발바와 믹틀란)까지 거슬러 올라갑니다. 지중해 지역에서는 제우스와 판 등의 신에게 바쳐진 그리스 신전이 동굴에 위치해 있었고, 남아시아에서는 아잔타와 엘레판타 등의 불교와 힌두교 동굴 사원이 기념비적인 종교 단지가 되었습니다. 여러 문화와 시대를 거쳐 동굴은 인간이 신성과 접촉하고자 하는 공간으로 꾸준히 사용되어 왔으며, 이는 동굴이 신비, 변화, 신성한 힘이 있는 자연적 장소로서 지속적인 역할을 했음을 보여줍니다.'),
('ko_KR', 'TXT_KEY_BUILDING_XUEMIAO_TEXT', '공묘는 고대 중국의 철학자이자 교사인 공자를 모신 사당입니다. 공자의 사상은 동아시아의 도덕, 정치, 교육 전통에 영향을 미쳤습니다. 건축학적으로 보면 황궁이나 중국의 고전 서원과 비슷하며, 종종 안뜰, 화려한 문, 석판, 제물을 바치는 홀이 특징입니다. 공묘에서 가장 눈에 띄는 건물은 대성전으로, 공자와 그의 저명한 제자들의 위패를 모시고 있습니다. 이러한 사원은 본래 신에게 기도를 올리는 예배 장소가 아니었지만, 문화적 조상이자 도덕적 모범이신 공자를 기리는 공간이었습니다. 이곳은 특히 공자의 생일을 기념하는 연례 행사 때 학문, 덕행, 학문적 업적을 기리는 제물을 바치는 중요한 의식 장소 역할을 했습니다.[NEWLINE][NEWLINE]공묘의 역사는 기원전 478년으로 거슬러 올라가는데, 당시 산둥성 곡부에 있던 공자의 옛집이 그를 기리는 최초의 사찰로 개조되었습니다. 당나라와 송나라 시대에는 공묘가 널리 퍼졌으며, 종종 학습의 중심지인 학교와 학원과 연계되었습니다. 명나라와 청나라는 디자인과 의례를 더욱 표준화하여 거의 모든 현에서 중요한 시민적, 교육적 랜드마크가 되었습니다. 중국을 넘어 한국, 일본, 베트남까지 유교 사원이 퍼져나갔으며, 그 곳에서도 학자들을 숭배하고 유교적 가치를 옹호하는 공간으로 기능했습니다. 오늘날 많은 공묘가 문화유산으로 남아 있으며, 동아시아 사회, 통치, 교육을 형성하는 데 있어 유교가 역사적으로 어떤 역할을 했는지를 보여줍니다.'),
('ko_KR', 'TXT_KEY_BUILDING_JINJA_TEXT', '신사는 일본 신토의 신전으로, 카미(신령이나 신)를 모시고 숭배하는 신성한 공간입니다. 일반적으로 신사의 입구에는 토리이 문이 있는데, 이는 일상 세계에서 신성 세계로의 전환을 상징합니다. 경내에는 정화소(테미즈야), 제물을 바치는 홀(하이덴), 가미의 영혼이 머무는 내부 성소(혼덴) 등의 시설이 있습니다. 신사는 기도와 종교의식을 위한 장소일 뿐만 아니라 축제(마츠리)가 열리는 지역 사회의 중심지이기도 하며, 지역 정체성과 자연의 계절 순환을 강화합니다. 각 신사의 건축 양식과 배치는 신, 지역, 역사적 시대에 따라 다르지만, 모두 인간, 자연, 신을 연결하는 지점 역할을 합니다.[NEWLINE][NEWLINE]신사의 역사는 일본 최초의 종교 활동 시대로 거슬러 올라가는데, 당시 숲, 산, 폭포와 같은 자연 장소가 신의 신성한 거주지로 숭배되었습니다. 시간이 흐르면서, 특히 야요이 시대와 고훈 시대(기원전 300년경~서기 538년경)에는 이러한 영혼을 기리고 모시는 영구적인 구조물이 지어졌습니다. 야마토 정권의 성장과 나라, 헤이안 시대에 신도 의식이 체계화되면서 신사는 지역 사회와 황실 모두에 연계되는 공식 기관이 되었습니다. 역사를 통틀어 이세 신궁, 이즈모 타이샤와 같은 주요 신사는 전국적인 명성을 얻었고, 수많은 지방 신사는 지역적 전통을 유지해 왔습니다. 불교가 전래되고 수 세기 동안 종교적 융합이 이루어진 이후에도 신사는 일본의 영성에서 중심적인 역할을 유지해 왔습니다. 오늘날에도 고대의 의례와 현대의 지역 사회 생활이 융합된, 중요한 문화적, 종교적 유적지로 남아 있습니다.'),
('ko_KR', 'TXT_KEY_BUILDING_GOMPA_TEXT', '티베트 곰파는 티베트 불교의 사원 또는 명상당으로, 예배 장소이자 학습의 중심지 역할을 합니다. 건축학적으로 보면, 곰파는 요새나 성벽으로 둘러싸인 단지와 비슷해 보이는데, 일반적으로 높은 지대에 지어지며, 하얗게 칠해진 벽, 평평한 지붕, 벽화, 탕카(성스러운 그림), 부처와 보살의 동상으로 장식된 밝게 칠해진 내부를 갖추고 있습니다. 사원 내부에는 보통 기도를 위한 대강당, 작은 사당, 승려들의 생활 공간이 있습니다. 곰파는 승려와 비구니를 수용하고, 불교 경전을 보존하고, 티베트 공동체의 종교적 삶을 지탱하는 축제, 의식, 가르침을 주최하는 영적 수행의 중심지 역할을 합니다.[NEWLINE][NEWLINE]티베트 곰파의 역사는 7세기로 거슬러 올라가는데, 당시 송찬간포 왕이 불교를 티베트에 처음 소개했습니다. 초기 수도원은 인도와 네팔의 불교 건축 양식에 영향을 받았고, 나중에는 토착 티베트 양식과 본교 전통이 융합되었습니다. 가장 오래되고 중요한 곰파 중 하나는 삼예사(Samye Monastery)로, 티베트에서 밀교(바즈라야나 불교)를 확립하는 데 중요한 역할을 한 파드마삼바바의 지도로 8세기에 지어졌습니다. 시간이 흐르면서 곰파는 영적 중심지일 뿐만 아니라 문화적, 정치적 기관으로서도 중요한 역할을 하게 되었으며, 격변의 시기에도 티베트의 종교적 전통을 보호했습니다. 오늘날, 20세기의 어려움에도 불구하고 티베트 곰파는 티베트, 인도, 네팔, 부탄과 전 세계 티베트 이주민 사회에서 계속 번성하고 있습니다.'),
